import assert from 'node:assert/strict';
import { createHash } from 'node:crypto';
import { readFileSync, writeFileSync, mkdirSync, mkdtempSync, realpathSync } from 'node:fs';
import { dirname, join, resolve } from 'node:path';
import { spawnSync } from 'node:child_process';

const root = realpathSync(process.cwd());
const { pathToFileURL } = await import('node:url');
const { releaseSteps, withReleaseStep } = await import(pathToFileURL(join(root,'scripts/lib/release-steps.mjs')));
const { materialSummary } = await import(pathToFileURL(join(root,'scripts/lib/material-summary.mjs')));
const { operationalFailures } = await import(pathToFileURL(join(root,'scripts/lib/plan-failures.mjs')));
assert.equal(spawnSync('git',['rev-parse','--show-toplevel'],{encoding:'utf8'}).stdout.trim(),root);
const seen = new Set(), pending = [join(root, 'scripts/release.mjs')];
const bareWorkspaceImports = [];
while (pending.length) {
  const file = pending.pop();
  if (seen.has(file)) continue;
  seen.add(file);
  assert.doesNotMatch(file.slice(root.length), /\/packages\/[^/]+\/dist\//);
  const source = readFileSync(file, 'utf8');
  for (const match of source.matchAll(/^\s*(?:import|export)\s+(?:[^;"']*?\bfrom\s*)?["']([^"']+)["']/gm)) {
    const specifier = match[1];
    if (specifier.startsWith('.')) pending.push(resolve(dirname(file), specifier));
    else if (specifier.startsWith('@dotln/')) bareWorkspaceImports.push(specifier);
  }
}
assert.deepEqual(bareWorkspaceImports, []);

const record = { steps: releaseSteps() };
assert.deepEqual(record.steps.map(s => s.name), ['prerequisites', 'runtime', 'worktree-removal', 'publication', 'starter-refresh', 'prune', 'record']);
const descriptor = Object.getOwnPropertyDescriptor(globalThis, 'performance');
let now = 0;
Object.defineProperty(globalThis, 'performance', { configurable: true, value: { now: () => now } });
try {
  await withReleaseStep(record, 'publication', async () => {
    now += 10;
    await withReleaseStep(record, 'prune', () => { now += 30; });
    now += 20;
  });
  await withReleaseStep(record, 'prune', () => { now += 10; });
  await assert.rejects(withReleaseStep(record, 'prune', () => { now += 5; throw new Error('probe failure'); }), /probe failure/);
  await withReleaseStep(record, 'publication', () => { now += 7; });
} finally {
  Object.defineProperty(globalThis, 'performance', descriptor);
}
assert.equal(record.steps.find(s => s.name === 'publication').durationMs, 37);
assert.equal(record.steps.find(s => s.name === 'prune').durationMs, 45);
assert.equal(record.steps.reduce((n,s) => n+s.durationMs,0), 82);
assert.deepEqual(record.steps.find(s => s.name === 'runtime'), { name:'runtime', startedAt:null, finishedAt:null, durationMs:0 });
for (const step of record.steps.filter(s => s.startedAt)) assert.ok(Date.parse(step.finishedAt) >= Date.parse(step.startedAt));

const paths = [{path:'unicode-\u00e9/line\nfile',class:'retained'},{path:'quote"/file',class:'intake'}];
const summary = materialSummary(paths);
assert.deepEqual(summary, materialSummary([...paths].reverse()));
assert.equal(summary.digest, 'sha256:'+createHash('sha256').update(JSON.stringify(paths.map(r=>r.path).sort())).digest('hex'));
assert.deepEqual(summary.countsByClass, {intake:1,retained:1});
assert.deepEqual(materialSummary([]).countsByClass, {});
assert.equal(materialSummary([]).count, 0);

const fixture = mkdtempSync(join(dirname(new URL(import.meta.url).pathname), 'reader-'));
const init = spawnSync('git',['init','-q','-b','main',fixture],{encoding:'utf8'});
assert.equal(init.status,0,init.stderr);
assert.equal(spawnSync('git',['-C',fixture,'rev-parse','--show-toplevel'],{encoding:'utf8'}).stdout.trim(),realpathSync(fixture));
const put = (file,value) => { mkdirSync(dirname(join(fixture,file)),{recursive:true}); writeFileSync(join(fixture,file),JSON.stringify(value)); };
const attempt = (index) => {
  const start = Date.UTC(2030,0,1)+index*60_000;
  return {startedAt:new Date(start).toISOString(),recordedAt:new Date(start+(index+1)*1000).toISOString(),publication:{tagOutcome:index===8?null:'published'},blockers:index===8?[{reason:'synthetic refusal'}]:[],dryRun:index===7,steps:[{name:'prune',durationMs:index*100}]};
};
const attempts=Array.from({length:10},(_,i)=>attempt(i));
put('docs/control/local/retained/WO-901/release-close.json',{...attempts[5],schemaVersion:1,workOrderId:'WO-901',previousAttempts:[...attempts.filter((_,i)=>i!==5).reverse(),{publication:{tagOutcome:null},blockers:[]},{...attempt(20),steps:[{name:'prune',durationMs:null}]}]});
const other={startedAt:'2030-01-01T00:20:00+00:00',recordedAt:'2030-01-01T00:22:00+00:00',publication:{tagOutcome:'published'},blockers:[],steps:[{name:'runtime',durationMs:55555},{name:'prune',durationMs:55555}]};
put('docs/control/local/retained/WO-902/release-close.json',{...other,schemaVersion:1,workOrderId:'WO-902'});
const control={orders:new Map(),eventSegments:new Map()};
const timing=operationalFailures(fixture,control,()=>true).localReleaseCloses.timing;
assert.equal(timing.sampleCount,8);
assert.equal(timing.medianTotalMs,7500);
assert.equal(timing.slowestStep.name,'prune');
assert.equal(timing.slowestStep.order,'WO-902');
assert.equal(timing.slowestStep.durationMs,55555);
assert.equal(operationalFailures(fixture,control,r=>r.order==='WO-901').localReleaseCloses.timing.medianTotalMs,6500);
assert.deepEqual(operationalFailures(fixture,control,()=>false).localReleaseCloses.timing,{sampleCount:0,medianTotalMs:null,slowestStep:null});

console.log(JSON.stringify({staticGraph:{files:seen.size,builtImports:0,bareWorkspaceImports:0},timers:{nestedExclusive:true,repeated:true,failureFinalized:true,skippedUntouched:true},material:{orderInvariant:true,unicodeAndNewline:true,empty:true},reader:{multiOrder:true,unorderedHistory:true,latestEight:true,malformedExcluded:true,windowFilter:true,tieByName:true,previewAndRefusalIncluded:true,timing}},null,2));
